/* @autogenerated */
import { CommonModule } from '@angular/common';
import { Component, computed, input, OnDestroy, OnInit, signal } from '@angular/core';
import { FormControl, ReactiveFormsModule, FormsModule } from '@angular/forms';
import { MatButtonToggleModule } from '@angular/material/button-toggle';
import { MatChipsModule } from '@angular/material/chips';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatSelectModule } from '@angular/material/select';
import { MatTabsModule } from '@angular/material/tabs';
import { TranslocoModule } from '@jsverse/transloco';
import { parseExpression } from 'cron-parser';
import { Subscription } from 'rxjs';
import { BaseEditable } from '../base-editable';
import { EditableHiddenMarkComponent } from '../editable-hidden-mark/editable-hidden-mark.component';

export type CronFrequency = 'minute' | 'hour' | 'day' | 'week' | 'month' | 'year' | 'custom';

interface CronState {
  frequency: CronFrequency;
  minute: number;
  hour: number;
  dayOfMonth: number;
  month: number;
  weekDays: number[];
  customExpr: string;
}

const WEEKDAYS = [
  { label: 'L', value: 1 },
  { label: 'M', value: 2 },
  { label: 'X', value: 3 },
  { label: 'J', value: 4 },
  { label: 'V', value: 5 },
  { label: 'S', value: 6 },
  { label: 'D', value: 0 },
];

const MONTHS = [
  { label: 'Enero', value: 1 },
  { label: 'Febrero', value: 2 },
  { label: 'Marzo', value: 3 },
  { label: 'Abril', value: 4 },
  { label: 'Mayo', value: 5 },
  { label: 'Junio', value: 6 },
  { label: 'Julio', value: 7 },
  { label: 'Agosto', value: 8 },
  { label: 'Septiembre', value: 9 },
  { label: 'Octubre', value: 10 },
  { label: 'Noviembre', value: 11 },
  { label: 'Diciembre', value: 12 },
];

const HOURS = Array.from({ length: 24 }, (_, i) => i);
const MINUTES = Array.from({ length: 60 }, (_, i) => i);
const DAYS = Array.from({ length: 31 }, (_, i) => i + 1);

@Component({
  selector: 'editable-cron',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    ReactiveFormsModule,
    MatFormFieldModule,
    MatInputModule,
    MatSelectModule,
    MatTabsModule,
    MatChipsModule,
    MatButtonToggleModule,
    TranslocoModule,
    EditableHiddenMarkComponent,
  ],
  providers: BaseEditable.getValidableAccessorProvider(EditableCronComponent),
  templateUrl: './editable-cron.component.html',
  styleUrls: ['./editable-cron.component.scss'],
})
export class EditableCronComponent extends BaseEditable<string> implements OnInit, OnDestroy {
  allowedFrequencies = input<CronFrequency[]>(['minute', 'hour', 'day', 'week', 'month', 'year', 'custom']);
  showPreview = input<boolean>(true);

  readonly weekdays = WEEKDAYS;
  readonly months = MONTHS;
  readonly hours = HOURS;
  readonly minutes = MINUTES;
  readonly days = DAYS;

  state = signal<CronState>({
    frequency: 'day',
    minute: 0,
    hour: 9,
    dayOfMonth: 1,
    month: 1,
    weekDays: [],
    customExpr: '* * * * *',
  });

  expression = computed(() => this.buildExpression(this.state()));

  nextRuns = computed(() => {
    try {
      const iter = parseExpression(this.expression());
      return Array.from({ length: 5 }, () => iter.next().toDate());
    } catch {
      return [];
    }
  });

  customControl = new FormControl<string>('* * * * *', { nonNullable: true });
  private subs = new Subscription();

  override ngOnInit(): void {
    super.ngOnInit();
    this.subs.add(
      this.control.valueChanges.subscribe((external: string | null) => {
        if (external) this.parseExternal(external);
      }),
    );
    this.subs.add(
      this.customControl.valueChanges.subscribe((v) => {
        if (this.state().frequency === 'custom') {
          this.patchState({ customExpr: v });
        }
      }),
    );
  }

  override ngOnDestroy(): void {
    this.subs.unsubscribe();
    super.ngOnDestroy();
  }

  setFrequency(freq: CronFrequency): void {
    this.patchState({ frequency: freq });
    this.emit();
  }

  patchState(partial: Partial<CronState>): void {
    this.state.update((s) => ({ ...s, ...partial }));
    this.emit();
  }

  toggleWeekday(day: number): void {
    const current = this.state().weekDays;
    const next = current.includes(day) ? current.filter((d) => d !== day) : [...current, day].sort();
    this.patchState({ weekDays: next });
  }

  isWeekdaySelected(day: number): boolean {
    return this.state().weekDays.includes(day);
  }

  override validate(_: any) {
    try {
      parseExpression(this.expression());
      return null;
    } catch {
      return { cronInvalidExpression: true };
    }
  }

  pad(n: number): string {
    return n.toString().padStart(2, '0');
  }

  private emit(): void {
    this.updateValue(this.expression());
  }

  private buildExpression(s: CronState): string {
    switch (s.frequency) {
      case 'minute':
        return '* * * * *';
      case 'hour':
        return `${s.minute} * * * *`;
      case 'day':
        return `${s.minute} ${s.hour} * * *`;
      case 'week': {
        const days = s.weekDays.length ? s.weekDays.join(',') : '*';
        return `${s.minute} ${s.hour} * * ${days}`;
      }
      case 'month':
        return `${s.minute} ${s.hour} ${s.dayOfMonth} * *`;
      case 'year':
        return `${s.minute} ${s.hour} ${s.dayOfMonth} ${s.month} *`;
      case 'custom':
        return s.customExpr;
    }
  }

  private parseExternal(expr: string): void {
    try {
      parseExpression(expr);
      this.patchState({ frequency: 'custom', customExpr: expr });
      this.customControl.patchValue(expr, { emitEvent: false });
    } catch {}
  }
}
